var css=document.createElement('style');css.textContent='.auth-user-name{display:flex;align-items:center;gap:0.4rem;padding:0.35rem 0.75rem;background:var(--primary-dim);border:1px solid rgba(168,85,247,0.35);border-radius:6px;font-family:var(--font-display);font-size:0.65rem;font-weight:700;letter-spacing:0.1em;color:var(--primary);cursor:pointer;transition:background .2s,border-color .2s,box-shadow .2s;user-select:none}.auth-user-name:hover{background:rgba(168,85,247,0.25);border-color:var(--primary);box-shadow:0 0 12px rgba(168,85,247,0.3)}#user-popup{display:none;position:fixed;top:64px;right:1.5rem;z-index:9998;background:var(--card);border:1px solid var(--border);border-radius:10px;width:280px;box-shadow:0 8px 40px rgba(0,0,0,0.6),0 0 24px rgba(168,85,247,0.1);overflow:hidden;animation:popIn .15s ease}#user-popup.open{display:block}@keyframes popIn{from{opacity:0;transform:translateY(-8px)}to{opacity:1;transform:translateY(0)}}.popup-header{padding:1rem 1.25rem .75rem;border-bottom:1px solid var(--border)}.popup-header-row{display:flex;align-items:center;gap:.75rem;cursor:pointer;border-radius:8px;padding:.35rem;margin:-.35rem;transition:background .15s}.popup-header-row:hover{background:rgba(168,85,247,0.08)}.popup-header-avatar{width:36px;height:36px;border-radius:999px;display:inline-flex;align-items:center;justify-content:center;overflow:hidden;background:rgba(168,85,247,0.15);border:1px solid rgba(168,85,247,0.3);font-size:.72rem;font-weight:700;color:var(--primary);flex-shrink:0}.popup-header-avatar img{width:100%;height:100%;object-fit:cover;border-radius:50%}.popup-header-meta{min-width:0;flex:1}.popup-header-label{font-size:.6rem;font-weight:700;letter-spacing:.15em;text-transform:uppercase;color:var(--muted);margin-bottom:.2rem}.popup-header-name{font-family:var(--font-display);font-size:.9rem;font-weight:700;color:var(--primary)}.popup-header-email{font-size:.75rem;color:var(--muted);margin-top:.1rem}.popup-section{padding:.5rem}.popup-section+.popup-section{border-top:1px solid var(--border)}.popup-btn{width:100%;display:flex;align-items:center;gap:.65rem;padding:.65rem .75rem;background:transparent;border:none;border-radius:6px;color:var(--text);font-family:var(--font-body);font-size:.85rem;font-weight:500;cursor:pointer;text-align:left;transition:background .15s,color .15s}.popup-btn:hover{background:rgba(255,255,255,0.05)}.popup-btn.danger{color:var(--danger)}.popup-btn.danger:hover{background:var(--danger-dim)}.popup-btn svg{flex-shrink:0;opacity:.7}.popup-inline-form{display:none;flex-direction:column;gap:.5rem;padding:.25rem .75rem .75rem}.popup-inline-form.open{display:flex}.popup-inline-form input{width:100%;background:#0d0d14;border:1px solid var(--border);border-radius:6px;padding:.6rem .75rem;color:var(--text);font-size:.85rem;font-family:var(--font-body);outline:none;transition:border-color .2s}.popup-inline-form input:focus{border-color:var(--primary)}.popup-inline-form-row{display:flex;gap:.5rem}.popup-save-btn{flex:1;padding:.5rem;background:var(--primary);color:#fff;border:none;border-radius:6px;font-family:var(--font-display);font-size:.6rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;cursor:pointer}.popup-cancel-btn{flex:1;padding:.5rem;background:transparent;color:var(--muted);border:1px solid var(--border);border-radius:6px;font-family:var(--font-display);font-size:.6rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase;cursor:pointer}.popup-msg{font-size:.75rem;padding:.3rem .1rem;display:none}.popup-msg.ok{display:block;color:#22c55e}.popup-msg.err{display:block;color:var(--danger)}.role-pill{display:inline-flex;align-items:center;gap:.3rem;padding:.28rem .65rem;border-radius:20px;font-size:.62rem;font-weight:700;letter-spacing:.1em;text-transform:uppercase}.role-pill.active{background:rgba(34,197,94,0.15);color:#22c55e;border:1px solid rgba(34,197,94,0.35)}.role-pill.inactive{background:rgba(239,68,68,0.12);color:var(--danger);border:1px solid rgba(239,68,68,0.3)}.role-pill.admin{background:rgba(168,85,247,0.15);color:var(--primary);border:1px solid rgba(168,85,247,0.35)}.role-pill.editor{background:rgba(34,211,238,0.15);color:var(--secondary);border:1px solid rgba(34,211,238,0.35)}.role-pill.orders{background:rgba(34,197,94,0.12);color:#22c55e;border:1px solid rgba(34,197,94,0.3)}.role-pill.job{background:rgba(251,191,36,0.12);color:#fbbf24;border:1px solid rgba(251,191,36,0.35)}.sidebar-size-option{display:flex;align-items:center;justify-content:center;gap:.35rem;padding:.5rem;border-radius:6px;font-family:var(--font-display);font-size:.6rem;font-weight:700;letter-spacing:.05em;text-transform:uppercase;cursor:pointer;transition:background .2s,border-color .2s,color .2s}.sidebar-size-option.active{background:rgba(168,85,247,0.15);color:var(--primary);border-color:var(--primary)}.popup-inline-form input::placeholder{color:var(--muted)}.popup-save-btn:hover{opacity:.85}';document.head.appendChild(css);

